-- IF NOT EXISTS: si la tabla ya existe, no hace nada.
-- Así se puede ejecutar en cada arranque sin errores.
CREATE TABLE IF NOT EXISTS libros (
    -- BIGINT: número entero grande, equivale a Long en Java.
    -- GENERATED BY DEFAULT AS IDENTITY: PostgreSQL asigna el id automáticamente (1, 2, 3...)
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    titulo  VARCHAR(200) NOT NULL UNIQUE,  -- UNIQUE: la base de datos impide títulos repetidos
    autor   VARCHAR(100) NOT NULL,
    paginas INTEGER      NOT NULL CHECK (paginas > 0)  -- CHECK: regla validada por PostgreSQL
);